const getFile = (relativePath) => files.get(relativePath) ?? utilitySources.get(relativePath) ?? ''

const expectContains = (relativePath, needle, message) => {
  if (!getFile(relativePath).includes(needle)) {
    addFailure(relativePath, message)
  }
}

const expectNotContains = (relativePath, needle, message) => {
  if (getFile(relativePath).includes(needle)) {
    addFailure(relativePath, message)
  }
}

const expectCountAtLeast = (relativePath, pattern, minCount, message) => {
  const source = getFile(relativePath)
  const count = source.match(pattern)?.length ?? 0
  if (count < minCount) {
    addFailure(relativePath, `${message}，当前 ${count}，期望至少 ${minCount}`)
  }
  return count
}

const extractObjectBlock = (source, marker) => {
  const markerIndex = source.indexOf(marker)
  if (markerIndex < 0) return ''
  const startIndex = source.indexOf('{', markerIndex)
  if (startIndex < 0) return ''
  let depth = 0
  for (let index = startIndex; index < source.length; index += 1) {
    const char = source[index]
    if (char === '{') depth += 1
    if (char === '}') {
      depth -= 1
      if (depth === 0) return source.slice(startIndex, index + 1)
    }
  }
  return ''
}

const expectMatrixEntriesHaveSinglePrimary = (relativePath, matrixName, expectedEntries) => {
  const matrixSource = extractObjectBlock(getFile(relativePath), matrixName)
  if (!matrixSource) {
    addFailure(relativePath, `${matrixName} 应定义显式动作矩阵`)
    return
  }

  for (const entryName of expectedEntries) {
    const entrySource = extractObjectBlock(matrixSource, `${entryName}:`)
    if (!entrySource) {
      addFailure(relativePath, `${matrixName} 应包含 ${entryName} 状态`)
      continue
    }
    const primaryCount = entrySource.match(/\bprimary\s*:/g)?.length ?? 0
    if (primaryCount !== 1) {
      addFailure(relativePath, `${matrixName}.${entryName} 应且只应定义一个推荐主行动，当前 ${primaryCount}`)
    }
  }
}

const onlineModuleShellPanelPages = [
  'online/OnlineCohabitationView.vue',
  'online/OnlineNeighborView.vue',
  'online/OnlineOrdersView.vue',
  'online/OnlineManorView.vue',
  'online/OnlineSocietyView.vue',
]

for (const [relativePath, source] of files.entries()) {
  for (const [tagName, expectedClass] of Object.entries(expectedControlClass)) {
    const tagPattern = new RegExp(`<${tagName}\\b(?:"[^"]*"|'[^']*'|[^'">])*>`, 'gis')
    const tags = source.match(tagPattern) ?? []
    for (const tag of tags) {
      const classMatch = tag.match(/\bclass\s*=\s*(["'])([\s\S]*?)\1/i)
      const classValue = classMatch?.[2] ?? ''
      const isHiddenFileInput = tagName === 'input' && /\btype\s*=\s*(["'])file\1/i.test(tag) && /\bhidden\b/.test(classValue)
      if (isHiddenFileInput) continue
      checkedControls += 1
      if (!classValue.includes(expectedClass)) {
        addFailure(relativePath, `${tagName} 控件没有复用 ${expectedClass}`)
      }
    }
  }
}

